// Extrair JSON da resposta do Gemini
const respostaGemini = $json;

// Função para extrair JSON de qualquer estrutura
function extrairJSON(objeto) {
  // Tenta diferentes caminhos para encontrar o texto
  let texto = null;

  // Caminho 1: candidates[0].content.parts[0].text
  if (objeto.candidates && objeto.candidates[0]?.content?.parts?.[0]?.text) {
    texto = objeto.candidates[0].content.parts[0].text;
  }
  // Caminho 2: content
  else if (objeto.content) {
    texto = JSON.stringify(objeto.content);
  }
  // Caminho 3: text direto
  else if (objeto.text) {
    texto = objeto.text;
  }
  // Caminho 4: resposta direta
  else if (typeof objeto === 'string') {
    texto = objeto;
  }

  if (!texto) {
    throw new Error('Não foi possível encontrar texto na resposta do Gemini');
  }

  // Limpa o texto
  texto = texto.trim();

  // Remove markdown code blocks se existirem
  texto = texto.replace(/```json/g, '').replace(/```/g, '');

  // Encontra o primeiro { e o último }
  const inicio = texto.indexOf('{');
  const fim = texto.lastIndexOf('}');

  if (inicio === -1 || fim === -1 || fim <= inicio) {
    throw new Error('JSON não encontrado na resposta');
  }

  const jsonString = texto.substring(inicio, fim + 1);

  try {
    const jsonParseado = JSON.parse(jsonString);
    return jsonParseado;
  } catch (e) {
    console.error('Erro ao parsear JSON:', e);
    console.error('String tentada:', jsonString);
    throw new Error('JSON inválido na resposta do Gemini');
  }
}

// Extrai o JSON
const resultado = extrairJSON(respostaGemini);

return [{
  json: resultado
}];

// Formatar resposta para o usuário
const respostaOperacao = $json;

let mensagemFinal = '';

if (respostaOperacao.sucesso) {
  mensagemFinal = `✅ ${respostaOperacao.mensagem}\n\n`;

  if (respostaOperacao.cliente) {
    const cliente = respostaOperacao.cliente;
    mensagemFinal += `📋 DADOS DO CLIENTE:\n`;
    mensagemFinal += `ID: ${cliente.id}\n`;
    mensagemFinal += `Nome: ${cliente.nome}\n`;
    if (cliente.email) mensagemFinal += `Email: ${cliente.email}\n`;
    if (cliente.telefone) mensagemFinal += `Telefone: ${cliente.telefone}\n`;
    if (cliente.dataCadastro) mensagemFinal += `Data Cadastro: ${cliente.dataCadastro}\n`;
    if (cliente.status) mensagemFinal += `Status: ${cliente.status}\n`;
  }
} else {
  mensagemFinal = `❌ ${respostaOperacao.mensagem}`;
}

return [{
  json: {
    sucesso: respostaOperacao.sucesso,
    mensagem: respostaOperacao.mensagem,
    resposta_completa: mensagemFinal,
    cliente: respostaOperacao.cliente || null
  }
}];
